import sys, json, time, os, numpy as np

def read_instance(path):
    with open(path, 'r') as f:
        data = json.load(f)
    n = data['n']
    A = np.array(data['A'], dtype=np.int64)
    B = np.array(data['B'], dtype=np.int64)
    return n, A, B

def cost(p, A, B):
    return np.sum(A * B[p][:, p])

def generate_initial_solution(n):
    perm = list(range(n))
    np.random.shuffle(perm)
    return perm

def two_swap(p):
    i, j = np.random.choice(len(p), 2, replace=False)
    p[i], p[j] = p[j], p[i]
    return p

def adaptive_two_swap_local_search(n, A, B, budget):
    start = time.time()
    current = generate_initial_solution(n)
    current_cost = cost(current, A, B)
    best = current[:]
    best_cost = current_cost
    temp = 1.0
    alpha = 0.9995
    while time.time() - start < budget:
        neighbor = two_swap(current[:])
        neighbor_cost = cost(neighbor, A, B)
        delta = neighbor_cost - current_cost
        if delta < 0 or np.random.rand() < np.exp(-delta / temp):
            current, current_cost = neighbor, neighbor_cost
            if neighbor_cost < best_cost:
                best, best_cost = neighbor[:], neighbor_cost
        temp *= alpha
        if temp < 1e-4:
            temp = 1.0
            current = generate_initial_solution(n)
            current_cost = cost(current, A, B)
    return best

def verify_solution(p, A, B):
    n = len(p)
    for i in range(n):
        for j in range(n):
            if not (0 <= p[i] < n and 0 <= p[j] < n):
                return False
    return True

def main():
    if len(sys.argv) < 3:
        return
    instance_path = sys.argv[1]
    budget = float(sys.argv[2])
    n, A, B = read_instance(instance_path)
    solution = adaptive_two_swap_local_search(n, A, B, budget)
    if not verify_solution(solution, A, B):
        return
    perm_1based = [x + 1 for x in solution]
    print("PERMUTATION: " + " ".join(map(str, perm_1based)))

if __name__ == "__main__":
    main()

